  "addRecord": { ts: "function addRecord(entity: string, row: Row): void {\r\n  (state.records[entity] ??= []).push({ ...row });\r\n}", js: "function addRecord(entity, row) {\n    var _a;\n    ((_a = state.records)[entity] ?? (_a[entity] = [])).push({ ...row });\n}", deps: ["Row","state"] },
  "seedRecords": { ts: "/** `n` numbered records (\"Recipe 1\", \"Recipe 2\", ...) with `nameKey` set. */\r\nfunction seedRecords(entity: string, nameKey: string, n: number): void {\r\n  state.records[entity] = Array.from({ length: n }, (_, i) => ({ [nameKey]: `${cap(entity)} ${i + 1}` }));\r\n}", js: "/** `n` numbered records (\"Recipe 1\", \"Recipe 2\", ...) with `nameKey` set. */\nfunction seedRecords(entity, nameKey, n) {\n    state.records[entity] = Array.from({ length: n }, (_, i) => ({ [nameKey]: `${cap(entity)} ${i + 1}` }));\n}", deps: ["state","cap"] },
