  "recordsCsv": { ts: "/** The records of an entity as CSV, for exports. */\r\nfunction recordsCsv(entity: string): string {\r\n  const rows = state.records[entity] ?? [];\r\n  const keys = Array.from(new Set(rows.flatMap((r) => Object.keys(r))));\r\n  return [keys.join(\",\"), ...rows.map((r) => keys.map((k) => JSON.stringify(r[k] ?? \"\")).join(\",\"))].join(\"\\n\");\r\n}", js: "/** The records of an entity as CSV, for exports. */\nfunction recordsCsv(entity) {\n    const rows = state.records[entity] ?? [];\n    const keys = Array.from(new Set(rows.flatMap((r) => Object.keys(r))));\n    return [keys.join(\",\"), ...rows.map((r) => keys.map((k) => JSON.stringify(r[k] ?? \"\")).join(\",\"))].join(\"\\n\");\n}", deps: ["state"] },
