  "checkUser": { ts: "function checkUser(email: string, password: string): boolean {\r\n  return state.users.some((u) => u.email === email.toLowerCase() && u.password === password);\r\n}", js: "function checkUser(email, password) {\n    return state.users.some((u) => u.email === email.toLowerCase() && u.password === password);\n}", deps: ["state"] },
