  "signIn": { ts: "/** Signs someone in and shows \"Signed in as ...\" with a user menu holding Sign out. */\r\nfunction signIn(who: string): void {\r\n  state.session = who;\r\n  state.attempts = 0;\r\n  if (state.wanted) {\r\n    showPage(state.wanted);\r\n    state.wanted = \"\";\r\n  }\r\n  const account = el(\"account\");\r\n  account.textContent = \"\";\r\n  account.append(make(\"span\", { class: \"muted\" }, `Signed in as ${who}`));\r\n  const menu = make(\"button\", { type: \"button\", \"aria-label\": \"User menu\", \"aria-haspopup\": \"menu\" }, \"Account\");\r\n  menu.style.marginLeft = \"10px\";\r\n  menu.addEventListener(\"click\", () => showMenu(\"account\", [\"sign out\"], () => signOut()));\r\n  account.append(menu);\r\n}", js: "/** Signs someone in and shows \"Signed in as ...\" with a user menu holding Sign out. */\nfunction signIn(who) {\n    state.session = who;\n    state.attempts = 0;\n    if (state.wanted) {\n        showPage(state.wanted);\n        state.wanted = \"\";\n    }\n    const account = el(\"account\");\n    account.textContent = \"\";\n    account.append(make(\"span\", { class: \"muted\" }, `Signed in as ${who}`));\n    const menu = make(\"button\", { type: \"button\", \"aria-label\": \"User menu\", \"aria-haspopup\": \"menu\" }, \"Account\");\n    menu.style.marginLeft = \"10px\";\n    menu.addEventListener(\"click\", () => showMenu(\"account\", [\"sign out\"], () => signOut()));\n    account.append(menu);\n}", deps: ["state","showPage","el","make","showMenu","signOut"] },
  "signOut": { ts: "function signOut(): void {\r\n  state.session = \"\";\r\n  const account = el(\"account\");\r\n  account.textContent = \"\";\r\n  const button = make(\"button\", { type: \"button\" }, \"Sign in\");\r\n  button.addEventListener(\"click\", () => showPage(\"sign in\"));\r\n  account.append(button);\r\n}", js: "function signOut() {\n    state.session = \"\";\n    const account = el(\"account\");\n    account.textContent = \"\";\n    const button = make(\"button\", { type: \"button\" }, \"Sign in\");\n    button.addEventListener(\"click\", () => showPage(\"sign in\"));\n    account.append(button);\n}", deps: ["state","el","make","showPage"] },
